//! Parity with scikit-learn. Reference values come from committed fixtures in
//! `tools/parity/fixtures`, generated by `tools/parity/generate_fixtures.py`.
//!
//! The starting centres are supplied to both implementations, so this compares
//! the Lloyd iteration itself. The k-means++ and random initialisations are not
//! compared, because their random number generators differ.

use std::collections::HashMap;
use std::path::PathBuf;

use tpt_ml_proven_clustering::KMeans;
use tpt_ml_proven_core::{ArrayView, DenseView, UnsupervisedEstimator};

const TOL: f64 = 1e-9;

struct Fixture {
    fields: HashMap<String, Vec<String>>,
}

impl Fixture {
    fn load(name: &str) -> Self {
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../tools/parity/fixtures")
            .join(format!("{name}.txt"));
        let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path:?}: {e}"));
        let mut fields = HashMap::new();
        for line in text
            .lines()
            .filter(|l| !l.starts_with('#') && !l.is_empty())
        {
            let mut parts = line.split_whitespace();
            let key = parts.next().unwrap().to_string();
            fields.insert(key, parts.map(str::to_string).collect());
        }
        Self { fields }
    }

    fn raw(&self, key: &str) -> &[String] {
        self.fields
            .get(key)
            .unwrap_or_else(|| panic!("missing field {key}"))
    }

    fn floats(&self, key: &str) -> Vec<f64> {
        self.raw(key).iter().map(|s| s.parse().unwrap()).collect()
    }

    fn usize(&self, key: &str) -> usize {
        self.raw(key)[0].parse().unwrap()
    }

    fn ints(&self, key: &str) -> Vec<usize> {
        self.raw(key).iter().map(|s| s.parse().unwrap()).collect()
    }
}

/// Relabels in order of first appearance, so label permutations compare equal.
fn canonical(labels: &[usize]) -> Vec<usize> {
    let mut seen: Vec<usize> = Vec::new();
    labels
        .iter()
        .map(|&l| match seen.iter().position(|&s| s == l) {
            Some(p) => p,
            None => {
                seen.push(l);
                seen.len() - 1
            }
        })
        .collect()
}

fn assert_close(actual: f64, expected: f64, what: &str) {
    let scale = 1.0 + expected.abs();
    assert!(
        (actual - expected).abs() <= TOL * scale,
        "{what}: {actual} vs scikit-learn {expected}"
    );
}

fn check_kmeans(name: &str) {
    let fx = Fixture::load(name);
    let (rows, cols, k) = (fx.usize("rows"), fx.usize("cols"), fx.usize("k"));
    let x = fx.floats("x");
    let mut km = KMeans::<f64>::new(k)
        .with_initial_centers(fx.floats("init"))
        .with_tol(0.0)
        .with_max_iter(1000);
    UnsupervisedEstimator::fit(&mut km, DenseView::new(&x, rows, cols).unwrap()).unwrap();

    assert_eq!(
        canonical(km.labels().unwrap()),
        canonical(&fx.ints("labels")),
        "{name}: labels"
    );
    let centers = km.cluster_centers().unwrap();
    let expected_centers = fx.floats("centers");
    for (idx, &e) in expected_centers.iter().enumerate() {
        assert_close(
            centers.get(idx / cols, idx % cols),
            e,
            &format!("{name}: centre[{idx}]"),
        );
    }
    assert_close(
        km.inertia().unwrap(),
        fx.floats("inertia")[0],
        &format!("{name}: inertia"),
    );
}

#[test]
fn kmeans_blobs_match_scikit_learn() {
    check_kmeans("kmeans_blobs_k4");
}

#[test]
fn kmeans_uniform_matches_scikit_learn() {
    check_kmeans("kmeans_uniform_k5");
}

#[test]
fn kmeans_single_cluster_matches_scikit_learn() {
    check_kmeans("kmeans_one_cluster");
}

/// DBSCAN labels must match scikit-learn exactly: both sides use the same labelling
/// order, so no normalisation is needed.
#[test]
fn dbscan_matches_scikit_learn_exactly() {
    use tpt_ml_proven_clustering::Dbscan;
    let fx = Fixture::load("dbscan_blobs_noise");
    let (rows, cols) = (fx.usize("rows"), fx.usize("cols"));
    let x = fx.floats("x");
    let eps: f64 = fx.raw("eps")[0].parse().unwrap();
    let min_samples = fx.usize("min_samples");

    let mut db = Dbscan::new(eps, min_samples);
    UnsupervisedEstimator::fit(&mut db, DenseView::new(&x, rows, cols).unwrap()).unwrap();

    let expected: Vec<i64> = fx
        .raw("labels")
        .iter()
        .map(|s| s.parse().unwrap())
        .collect();
    assert_eq!(db.labels().unwrap(), expected.as_slice(), "labels");
    assert_eq!(
        db.core_sample_indices().unwrap(),
        fx.ints("core").as_slice(),
        "core samples"
    );
}
